"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["54222"],{31170(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_etapa.prazo_sem_unidade_declaravel","status":422,"titulo":"O prazo do recurso precisa declarar dias \xfateis ou horas"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_recurso_da_etapa.prazo_sem_unidade_declaravel","requisitos":["UNI-REQ-0113"],"oQueAconteceu":["O prazo declarado pela configura\xe7\xe3o do recurso de uma etapa n\xe3o traz a unidade, ou traz uma unidade que n\xe3o existe. Isso vale para os dois prazos da configura\xe7\xe3o: o de **interposi\xe7\xe3o**, na 1\xaa inst\xe2ncia, e o da **2\xaa inst\xe2ncia**. A recusa sai com **422**, nada \xe9 gravado, e o campo recusado \xe9 `etapas[i].recursos[j].prazoUnidade` (interposi\xe7\xe3o) ou `etapas[i].recursos[j].prazoSegundaInstanciaUnidade` (2\xaa inst\xe2ncia), em que `i` \xe9 a posi\xe7\xe3o da etapa e `j`, a do recurso na etapa.","A mensagem da resposta diz qual dos prazos foi recusado: \\"Informe a unidade do prazo de interposi\xe7\xe3o: dias \xfateis ou horas.\\" ou a mesma frase com \\"prazo da 2\xaa inst\xe2ncia\\". Um valor sozinho n\xe3o diz em que tempo o prazo corre (UNI-REQ-0113)."],"comoResolver":["Informe a unidade do prazo: `DIAS_UTEIS` ou `HORAS`. Dias corridos n\xe3o s\xe3o aceitos, e t\xeam [causa pr\xf3pria](/erros/uniplus.selecao.configuracao_do_recurso_da_etapa.prazo_em_dias_corridos)."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo","Leitura do documento de configura\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do recurso da etapa"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);